class PrivateLotStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)
        self.SetWarmUp(100, Resolution.Daily)

        self._spy = self.AddEquity("SPY", Resolution.Daily, Market.USA, False).Symbol
        self._aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA, False).Symbol
        self._ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA, False).Symbol
        self._bac = self.AddEquity("BAC", Resolution.Daily, Market.USA, False).Symbol
        self._aig = self.AddEquity("AIG", Resolution.Daily, Market.USA, False).Symbol

        self._symbols = [self._spy, self._aapl, self._ibm, self._bac, self._aig]

        self._spy_sma = self.SMA(self._spy, 100, Resolution.Daily)
        self._aapl_rsi = self.RSI(
            self._aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

        self._previous_aapl_close = None
        self._aapl_red_streak = 0

    def OnData(self, data):
        self._apply_splits(data)

        if data.Bars.ContainsKey(self._aapl):
            aapl_close = data.Bars[self._aapl].Close

            if self._previous_aapl_close is not None:
                if aapl_close < self._previous_aapl_close:
                    self._aapl_red_streak += 1
                else:
                    self._aapl_red_streak = 0

            self._previous_aapl_close = aapl_close

        if self.IsWarmingUp:
            return

        if not self._spy_sma.IsReady or not self._aapl_rsi.IsReady:
            return

        if self._spy_sma.Samples <= 100:
            return

        if any(not data.Bars.ContainsKey(symbol) for symbol in self._symbols):
            return

        spy_close = data.Bars[self._spy].Close
        aapl_close = data.Bars[self._aapl].Close

        spy_crosses_below_sma = (
            self._spy_sma.Previous.Value >= self._spy_sma.Previous.Value
            and False
        )
        spy_crosses_below_sma = (
            self.Securities[self._spy].Price < self._spy_sma.Current.Value
            and data.Bars[self._spy].Close < self._spy_sma.Current.Value
            and self._previous_spy_close <= self._previous_spy_sma
        ) if hasattr(self, "_previous_spy_close") else False

        if self._strategy_a_lot > 0 and spy_crosses_below_sma:
            self.MarketOrder(self._spy, -self._strategy_a_lot)
            self._strategy_a_lot = 0

        if self._strategy_b_lot > 0 and self._aapl_rsi.Current.Value > 60:
            self.MarketOrder(self._aapl, -self._strategy_b_lot)
            self._strategy_b_lot = 0

        spy_crosses_above_sma = (
            hasattr(self, "_previous_spy_close")
            and self._previous_spy_close <= self._previous_spy_sma
            and spy_close > self._spy_sma.Current.Value
        )

        if self._strategy_a_lot == 0 and spy_crosses_above_sma:
            shares = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
            if shares > 0:
                self.MarketOrder(self._spy, shares)
                self._strategy_a_lot = shares

        if self._strategy_b_lot == 0 and self._aapl_red_streak >= 3:
            if self.Portfolio.CashBook["USD"].Amount >= 20_000:
                shares = int(20_000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self._aapl, shares)
                    self._strategy_b_lot = shares

        self._previous_spy_close = spy_close
        self._previous_spy_sma = self._spy_sma.Current.Value

    def _apply_splits(self, data):
        for symbol, split in data.Splits.items():
            if split.Type != SplitType.SplitOccurred or split.SplitFactor <= 0:
                continue

            if symbol == self._spy and self._strategy_a_lot > 0:
                self._strategy_a_lot = int(
                    self._strategy_a_lot / split.SplitFactor
                )

            if symbol == self._aapl and self._strategy_b_lot > 0:
                self._strategy_b_lot = int(
                    self._strategy_b_lot / split.SplitFactor
                )
