from AlgorithmImports import *


class IndependentTwoSlotStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self._symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self._spy_closes = RollingWindow[float](101)
        self._aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self._aapl_previous_close = None
        self._aapl_red_streak = 0

        self._a_shares = 0
        self._b_shares = 0

        self._pending_orders = {}

    def OnData(self, data: Slice):
        # Market-state quantities update whenever their own data is available.
        if data.Bars.ContainsKey(self.spy):
            self._spy_closes.Add(float(data.Bars[self.spy].Close))

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = float(data.Bars[self.aapl].Close)

            if self._aapl_previous_close is not None:
                if aapl_close < self._aapl_previous_close:
                    self._aapl_red_streak += 1
                else:
                    self._aapl_red_streak = 0

            self._aapl_previous_close = aapl_close

        # Skip every rule evaluation if any subscribed ticker is missing today.
        if not all(data.Bars.ContainsKey(symbol) for symbol in self._symbols):
            return

        # Do not trade until every indicator/window used by a rule is fully formed.
        if self._spy_closes.Count < 101 or not self._aapl_rsi.IsReady:
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        current_spy_sma = sum(self._spy_closes[i] for i in range(100)) / 100.0
        previous_spy_sma = sum(self._spy_closes[i] for i in range(1, 101)) / 100.0
        previous_spy_close = self._spy_closes[1]

        spy_crosses_above_sma = (
            previous_spy_close <= previous_spy_sma
            and spy_close > current_spy_sma
        )
        spy_crosses_below_sma = (
            previous_spy_close >= previous_spy_sma
            and spy_close < current_spy_sma
        )

        # Evaluate all sells before any buys.
        if self._a_shares > 0 and not self._has_pending_order("A"):
            if spy_crosses_below_sma:
                self._submit_order("A", self.spy, -self._a_shares)

        if self._b_shares > 0 and not self._has_pending_order("B"):
            if self._aapl_rsi.Current.Value > 60:
                self._submit_order("B", self.aapl, -self._b_shares)

        # Slot 1: Strategy A.
        if self._a_shares == 0 and not self._has_pending_order("A"):
            if spy_crosses_above_sma and spy_close > 0:
                quantity = int(
                    (float(self.Portfolio.TotalPortfolioValue) * 0.40) / spy_close
                )
                if quantity > 0:
                    self._submit_order("A", self.spy, quantity)

        # Slot 2: Strategy B.
        if self._b_shares == 0 and not self._has_pending_order("B"):
            if self._aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                quantity = int(20_000 / aapl_close)
                if quantity > 0:
                    self._submit_order("B", self.aapl, quantity)

    def _submit_order(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity, tag=strategy)
        self._pending_orders[ticket.OrderId] = strategy

    def _has_pending_order(self, strategy):
        return strategy in self._pending_orders.values()

    def OnOrderEvent(self, order_event: OrderEvent):
        strategy = self._pending_orders.get(order_event.OrderId)

        if strategy is None:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            filled_quantity = int(order_event.FillQuantity)

            if strategy == "A":
                self._a_shares = max(0, self._a_shares + filled_quantity)
            elif strategy == "B":
                self._b_shares = max(0, self._b_shares + filled_quantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self._pending_orders[order_event.OrderId]
